16→/**
17→ * Generates a slug that is unique per shop.
18→ * Appends a counter suffix if the base slug is already taken.
19→ */
20→export async function generateUniqueSlug(shop: string, title: string): Promise<string> {
21→  const base = slugify(title) || "quiz";
22→  let slug = base;
23→  let counter = 0;
24→  while (await db.quiz.findFirst({ where: { shop, slug } })) {
25→    counter++;
26→    slug = `${base}-${counter}`;
27→  }
28→  return slug;
29→}
