31→/**
32→ * Safely parses a JSON string, returning `fallback` on any parse error.
33→ * Use this for all Prisma JSON string fields (Law 6).
34→ */
35→export function parseSafe<T>(str: string, fallback: T): T {
36→  try {
37→    return JSON.parse(str) as T;
38→  } catch {
39→    return fallback;
40→  }
41→}
