/**
 * scoring.ts — Score calculation helpers for the QuizSnap recommendation engine.
 *
 * All functions are pure (no I/O) and safe to import from server-side code.
 * Tag comparisons are always case-insensitive (Architecture Law 6 / engine spec).
 */

/**
 * Normalises a tag string to lowercase and trims whitespace so that
 * comparisons are always case-insensitive.
 */
export function normaliseTag(tag: string): string {
  return tag.toLowerCase().trim();
}

/**
 * Normalises an array of tags.
 */
export function normaliseTags(tags: string[]): string[] {
  return tags.map(normaliseTag);
}

/**
 * Given the quiz-accumulated tag counts (Record<tag, count>) and the set of
 * tags belonging to a single product, returns the aggregate relevance score
 * contributed purely by tag overlap.
 *
 * Each product tag that appears in `tagCounts` contributes its count value —
 * i.e. a tag chosen three times across different answers contributes 3, not 1.
 *
 * @param tagCounts  - Map of normalised tag → how many times it was selected
 * @param productTags - Normalised tags from the ProductMapping record
 * @returns { tagScore, matchedTags }
 */
export function computeTagScore(
  tagCounts: Record<string, number>,
  productTags: string[]
): { tagScore: number; matchedTags: string[] } {
  let tagScore = 0;
  const matchedTags: string[] = [];

  for (const tag of productTags) {
    const count = tagCounts[normaliseTag(tag)];
    if (count !== undefined && count > 0) {
      tagScore += count;
      matchedTags.push(tag);
    }
  }

  return { tagScore, matchedTags };
}

/**
 * Calculates the final relevance score for a single product by combining the
 * tag-overlap score with the product's configured base score.
 *
 * Formula: relevanceScore = tagScore + baseScore
 *
 * @param tagScore  - Score from tag overlap (see computeTagScore)
 * @param baseScore - ProductMapping.score (merchant-configured weight)
 * @returns combined relevance score
 */
export function computeRelevanceScore(tagScore: number, baseScore: number): number {
  return tagScore + baseScore;
}

/**
 * Converts a tagCounts record so every key is normalised (lowercase + trimmed).
 * Safe to call multiple times — idempotent.
 */
export function normaliseTagCounts(
  tagCounts: Record<string, number>
): Record<string, number> {
  const result: Record<string, number> = {};
  for (const [tag, count] of Object.entries(tagCounts)) {
    const key = normaliseTag(tag);
    result[key] = (result[key] ?? 0) + count;
  }
  return result;
}

/**
 * Checks whether all entries in `tagCounts` have a value of 0.
 * Used to detect the "no quiz answer selected any tags" edge case so the
 * recommendation engine can fall back to base-score ranking.
 */
export function isTagCountsEmpty(tagCounts: Record<string, number>): boolean {
  return Object.values(tagCounts).every((v) => v === 0);
}

/**
 * recommendation.server.ts — Product recommendation engine for QuizSnap.
 *
 * Never import this file from client components. All DB access and scoring
 * logic lives here on the server.
 *
 * Architecture compliance:
 *   Law 2  — every query is scoped by shop AND status = "active"
 *   Law 6  — all JSON fields parsed with parseSafe + documented fallback
 *   Law 7  — strict TypeScript, zero `any`, zero `@ts-ignore`
 *   Law 15 — ProductMappings are never hard-deleted; status = "archived" hides them
 */

import db from "../db.server";
import { parseSafe } from "../utils/helpers";
import {
  normaliseTagCounts,
  isTagCountsEmpty,
  computeTagScore,
  computeRelevanceScore,
  normaliseTags,
} from "../utils/scoring";

// ─── Public types ─────────────────────────────────────────────────────────────

export interface RecommendedProduct {
  productGid: string;
  title: string;
  handle: string | null;
  imageUrl: string | null;
  priceMin: number | null;
  priceMax: number | null;
  /** Combined tag-overlap + base-score relevance value. */
  relevanceScore: number;
  /** Subset of the product's tags that actually matched quiz answer tags. */
  matchedTags: string[];
}

export interface RecommendationOptions {
  /** Maximum number of products to return. Defaults to 4. */
  limit?: number;
  /** Product GIDs to exclude from results (e.g. already shown). */
  excludeGids?: string[];
  /** When supplied, only products in this collection GID are returned. */
  collectionFilter?: string;
  /** Only return products whose priceMin is >= this value. */
  minPrice?: number;
  /** Only return products whose priceMax is <= this value. */
  maxPrice?: number;
}

// ─── Internal shape for a raw ProductMapping row ──────────────────────────────

interface RawProductMapping {
  productGid: string;
  title: string;
  handle: string | null;
  imageUrl: string | null;
  tags: string;
  score: number;
  collections: string;
  priceMin: number | null;
  priceMax: number | null;
}

// ─── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Fetches all active ProductMapping rows for a shop in a single query.
 * Scoped by shop + status (Law 2 / Law 15).
 */
async function fetchActiveMappings(shop: string): Promise<RawProductMapping[]> {
  return db.productMapping.findMany({
    where: { shop, status: "active" },
    select: {
      productGid: true,
      title: true,
      handle: true,
      imageUrl: true,
      tags: true,
      score: true,
      collections: true,
      priceMin: true,
      priceMax: true,
    },
  });
}

/**
 * Applies optional post-score filters (collection, price, exclusions) to an
 * already-scored + sorted list.
 */
function applyFilters(
  products: RecommendedProduct[],
  rawMappings: RawProductMapping[],
  options: RecommendationOptions
): RecommendedProduct[] {
  const { excludeGids, collectionFilter, minPrice, maxPrice } = options;

  return products.filter((p) => {
    // Exclusion list
    if (excludeGids && excludeGids.includes(p.productGid)) return false;

    // Price range — skip null prices when a filter is requested
    if (minPrice !== undefined) {
      if (p.priceMin === null || p.priceMin < minPrice) return false;
    }
    if (maxPrice !== undefined) {
      if (p.priceMax === null || p.priceMax > maxPrice) return false;
    }

    // Collection filter — look up the raw row to parse collections JSON
    if (collectionFilter) {
      const raw = rawMappings.find((m) => m.productGid === p.productGid);
      const collections = parseSafe<string[]>(raw?.collections ?? "[]", []);
      if (!collections.includes(collectionFilter)) return false;
    }

    return true;
  });
}

/**
 * Converts a RawProductMapping into a RecommendedProduct with a pre-computed
 * relevance score based on the provided normalised tagCounts.
 */
function scoreMapping(
  raw: RawProductMapping,
  normalisedTagCounts: Record<string, number>
): RecommendedProduct {
  const productTags = parseSafe<string[]>(raw.tags, []);
  const { tagScore, matchedTags } = computeTagScore(normalisedTagCounts, productTags);
  const relevanceScore = computeRelevanceScore(tagScore, raw.score);

  return {
    productGid: raw.productGid,
    title: raw.title,
    handle: raw.handle,
    imageUrl: raw.imageUrl,
    priceMin: raw.priceMin,
    priceMax: raw.priceMax,
    relevanceScore,
    matchedTags,
  };
}

/**
 * Sorts a list of RecommendedProduct by:
 *   1. relevanceScore descending (primary)
 *   2. priceMin ascending as a tiebreaker (cheaper first)
 */
function sortByRelevance(products: RecommendedProduct[]): RecommendedProduct[] {
  return [...products].sort(
    (a, b) =>
      b.relevanceScore - a.relevanceScore ||
      (a.priceMin ?? 0) - (b.priceMin ?? 0)
  );
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Primary recommendation function.
 *
 * Fetches all active products for the shop, scores each one using the quiz
 * response's accumulated tagCounts (plus the product's base score), applies
 * any optional filters, and returns the top `limit` results.
 *
 * When no products score > 0 (i.e. no tag overlap and all base scores are 0,
 * or tagCounts is empty), this delegates to `getFallbackProducts` so the
 * results page is never empty.
 *
 * @param shop      - Shopify shop domain (always from session, never client)
 * @param tagCounts - Accumulated tag weights from quiz answer selection
 * @param options   - Optional limit, exclusions, collection filter, price range
 */
export async function getRecommendations(
  shop: string,
  tagCounts: Record<string, number>,
  options: RecommendationOptions = {}
): Promise<RecommendedProduct[]> {
  const limit = options.limit ?? 4;

  const rawMappings = await fetchActiveMappings(shop);

  // Guard: no products synced yet
  if (rawMappings.length === 0) return [];

  // Guard: empty or all-zero tag counts → skip scoring, go straight to fallback
  if (isTagCountsEmpty(tagCounts) || Object.keys(tagCounts).length === 0) {
    return getFallbackProducts(shop, limit);
  }

  const normalisedCounts = normaliseTagCounts(tagCounts);

  const scored = rawMappings.map((raw) => scoreMapping(raw, normalisedCounts));

  // Only keep products with a positive relevance score
  const positive = scored.filter((p) => p.relevanceScore > 0);

  const sorted = sortByRelevance(positive);

  const filtered = applyFilters(sorted, rawMappings, options);

  // Guarantee: if filters removed everything, fall back to top scored (no collection/price constraint)
  if (filtered.length === 0) {
    const fallback = applyFilters(sorted, rawMappings, {
      excludeGids: options.excludeGids,
    });
    if (fallback.length > 0) return fallback.slice(0, limit);
    return getFallbackProducts(shop, limit);
  }

  return filtered.slice(0, limit);
}

/**
 * Tag-match mode recommendation.
 *
 * Simpler than `getRecommendations`: finds products where ANY of their tags
 * appears in the provided `tags` array, then ranks by number of matching tags.
 * Used when a ResultPage has type = "tag-match".
 *
 * @param shop  - Shopify shop domain
 * @param tags  - Tags to match against (e.g. from ResultPage.matchTags)
 * @param limit - Maximum products to return (default 4)
 */
export async function getProductsByTags(
  shop: string,
  tags: string[],
  limit: number = 4
): Promise<RecommendedProduct[]> {
  if (tags.length === 0) return getFallbackProducts(shop, limit);

  const rawMappings = await fetchActiveMappings(shop);
  if (rawMappings.length === 0) return [];

  const normalisedInput = normaliseTags(tags);

  // Build a synthetic tagCounts where every provided tag has weight 1
  const tagCounts: Record<string, number> = {};
  for (const tag of normalisedInput) {
    tagCounts[tag] = 1;
  }

  const scored = rawMappings
    .map((raw) => scoreMapping(raw, tagCounts))
    .filter((p) => p.matchedTags.length > 0)
    .sort(
      (a, b) =>
        b.matchedTags.length - a.matchedTags.length ||
        b.relevanceScore - a.relevanceScore ||
        (a.priceMin ?? 0) - (b.priceMin ?? 0)
    );

  if (scored.length === 0) return getFallbackProducts(shop, limit);

  return scored.slice(0, limit);
}

/**
 * Direct GID lookup.
 *
 * Returns products by their Shopify GIDs in the order the GIDs are supplied.
 * Used for manual product selection on a ResultPage or cart integration.
 *
 * Only active products are returned (archived mappings are silently omitted).
 *
 * @param shop - Shopify shop domain
 * @param gids - Shopify product GIDs to fetch
 */
export async function getProductsByGids(
  shop: string,
  gids: string[]
): Promise<RecommendedProduct[]> {
  if (gids.length === 0) return [];

  const rows = await db.productMapping.findMany({
    where: {
      shop,
      status: "active",
      productGid: { in: gids },
    },
    select: {
      productGid: true,
      title: true,
      handle: true,
      imageUrl: true,
      tags: true,
      score: true,
      collections: true,
      priceMin: true,
      priceMax: true,
    },
  });

  // Preserve the caller's ordering
  const byGid = new Map(rows.map((r) => [r.productGid, r]));

  return gids.flatMap((gid) => {
    const raw = byGid.get(gid);
    if (!raw) return [];
    return [
      {
        productGid: raw.productGid,
        title: raw.title,
        handle: raw.handle,
        imageUrl: raw.imageUrl,
        priceMin: raw.priceMin,
        priceMax: raw.priceMax,
        relevanceScore: raw.score,
        matchedTags: [],
      } satisfies RecommendedProduct,
    ];
  });
}

/**
 * Fallback products.
 *
 * When no tag overlap exists (or all scored products were filtered out), this
 * returns the top products ordered by their base score descending so the
 * results page is never shown empty.
 *
 * Fulfils the "always return something" guarantee from the engine spec.
 *
 * @param shop  - Shopify shop domain
 * @param limit - Maximum products to return (default 4)
 */
export async function getFallbackProducts(
  shop: string,
  limit: number = 4
): Promise<RecommendedProduct[]> {
  const rows = await db.productMapping.findMany({
    where: { shop, status: "active" },
    orderBy: { score: "desc" },
    take: limit,
    select: {
      productGid: true,
      title: true,
      handle: true,
      imageUrl: true,
      priceMin: true,
      priceMax: true,
      score: true,
    },
  });

  return rows.map((r) => ({
    productGid: r.productGid,
    title: r.title,
    handle: r.handle,
    imageUrl: r.imageUrl,
    priceMin: r.priceMin,
    priceMax: r.priceMax,
    relevanceScore: r.score,
    matchedTags: [],
  }));
}
